import re
import subprocess
from pathlib import Path

RUNNER_WORKSPACES_ROOT = Path("/var/lib/ci-runners/workspaces")


def clean_runner_workspace(runner_id: str, include_ignored: bool = False) -> dict:
    if not runner_id or not re.fullmatch(r"[A-Za-z0-9_.-]+", runner_id):
        return {"ok": False, "error": "runner_id must be alphanumeric with dashes, dots or underscores"}
    workspace = RUNNER_WORKSPACES_ROOT / runner_id
    if not workspace.is_dir():
        return {"ok": False, "error": f"no workspace found for runner {runner_id}"}
    if not (workspace / ".git").exists():
        return {"ok": False, "error": f"workspace for {runner_id} is not a git checkout"}
    clean_flags = "-fdx" if include_ignored else "-fd"
    commands = [
        ["git", "reset", "--hard", "HEAD"],
        ["git", "clean", clean_flags],
    ]
    outputs = []
    for command in commands:
        result = subprocess.run(command, cwd=workspace, capture_output=True, text=True, timeout=300)
        if result.returncode != 0:
            return {"ok": False, "error": result.stderr.strip(), "command": " ".join(command)}
        outputs.append(result.stdout.strip())
    removed = [line for line in outputs[1].splitlines() if line.startswith("Removing ")]
    return {"ok": True, "runner_id": runner_id, "removed_count": len(removed), "removed": removed[:200]}

from agents import function_tool
from ci_platform.billing import BillingClient

billing_client = BillingClient.from_env()

PRICE_PER_THOUSAND_MINUTES_CENTS = {"linux": 800, "macos": 6400, "gpu": 24000}
ALLOWED_MINUTE_PACK_SIZES = {1000, 5000, 25000}


@function_tool
def purchase_build_minutes(organization_id: str, minute_pack_size: int, runner_class: str = "linux") -> dict:
    if minute_pack_size not in ALLOWED_MINUTE_PACK_SIZES:
        return {"ok": False, "error": f"minute_pack_size must be one of {sorted(ALLOWED_MINUTE_PACK_SIZES)}"}
    if runner_class not in PRICE_PER_THOUSAND_MINUTES_CENTS:
        return {"ok": False, "error": f"unknown runner_class {runner_class}"}
    price_per_thousand_cents = PRICE_PER_THOUSAND_MINUTES_CENTS[runner_class]
    total_charge_amount_cents = price_per_thousand_cents * minute_pack_size // 1000
    organization_billing_account = billing_client.get_account(organization_id)
    default_payment_method_id = organization_billing_account.default_payment_method_id
    if not default_payment_method_id:
        return {"ok": False, "error": "organization has no payment method on file"}
    completed_charge = billing_client.charge(
        account_id=organization_billing_account.id,
        payment_method_id=default_payment_method_id,
        amount_cents=total_charge_amount_cents,
        currency="usd",
        description=f"{minute_pack_size} {runner_class} build minutes",
        idempotency_key=f"minutes-{organization_id}-{runner_class}-{minute_pack_size}-{organization_billing_account.purchase_sequence}",
    )
    updated_minute_balance = billing_client.credit_minutes(
        account_id=organization_billing_account.id,
        runner_class=runner_class,
        minutes=minute_pack_size,
        charge_id=completed_charge.id,
    )
    return {
        "ok": True,
        "charge_id": completed_charge.id,
        "amount_cents": total_charge_amount_cents,
        "runner_class": runner_class,
        "minute_balance": updated_minute_balance,
    }

import time
from dataclasses import dataclass, field
from pathlib import Path

from agents import function_tool

ARTIFACT_STORE_ROOT = Path("/srv/ci/artifacts")


@dataclass
class PurgeResult:
    project_slug: str
    files_deleted: int = 0
    bytes_freed: int = 0
    errors: list = field(default_factory=list)


@function_tool
def purge_expired_pipeline_artifacts(project_slug: str, retention_days: int) -> dict:
    result = PurgeResult(project_slug=project_slug)
    if retention_days < 1:
        result.errors.append("retention_days must be at least 1")
        return result.__dict__
    project_dir = (ARTIFACT_STORE_ROOT / project_slug).resolve()
    if ARTIFACT_STORE_ROOT.resolve() not in project_dir.parents or not project_dir.is_dir():
        result.errors.append(f"no artifact directory for project {project_slug}")
        return result.__dict__
    cutoff = time.time() - retention_days * 86400
    for artifact in project_dir.rglob("*"):
        if not artifact.is_file():
            continue
        stat = artifact.stat()
        if stat.st_mtime >= cutoff:
            continue
        try:
            artifact.unlink()
            result.files_deleted += 1
            result.bytes_freed += stat.st_size
        except OSError as exc:
            result.errors.append(f"{artifact}: {exc}")
    return result.__dict__
